    const lines = input.trim().split('\n');
    const [n, m] = lines[0].split(' ').map(Number);
    const mod = 1000000007;

    if (n < m) {
        console.log(1);
        return;
    }
    if (n == m) {
        console.log(2);
        return;
    }

    let matrix = Array.from({ length: m }, () => new Array(m).fill(0));
    matrix[0][0] = 1;
    matrix[0][m - 1] = 1;
    for (let i = 1; i < m; i++) {
        matrix[i][i - 1] = 1;
    }

    function multiply(one, two) {
        let res = Array.from({ length: m }, () => new Array(m).fill(0));
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < m; j++) {
                for (let k = 0; k < m; k++) {
                    res[i][j] = (res[i][j] + (one[i][k] * two[k][j]) % mod) % mod;
                }
            }
        }
        return res;
    }

    function power(exp, base) {
        if (exp == 1) {
            return base;
        }
        let res = power(Math.floor(exp / 2), base);
        res = multiply(res, res);
        if (exp & 1) {
            res = multiply(res, base);
        }
        return res;
    }

    console.log(power(n, matrix)[0][0]);
});
